package android.view; public final class WindowMetrics { private final android.graphics.Rect bounds; private final WindowInsets insets; public WindowMetrics(android.graphics.Rect bounds, WindowInsets insets) { this.bounds = bounds; this.insets = insets; } public android.graphics.Rect getBounds() { return new android.graphics.Rect(bounds); } public WindowInsets getWindowInsets() { return insets; } }
